def monitor_resource_connection_state(resource, callback, exit_event=None):
    """Coroutine that monitors a KATCPResource's connection state.

    Calls callback(True/False) whenever the resource becomes connected or disconnected. Will
    always do an initial callback(False) call. Exits without calling callback() if
    exit_event is set
    """
    while not exit_event.is_set():
        if resource.req.connected:
            callback(True)
        elif not resource.req.connected:
            callback(False)
        yield from asyncio.sleep(0.5)


def monitor_resource_connection_and_sync_state(resource, callback, exit_event=None):
    """Coroutine that monitors a KATCPResource's connection and sync state.

    Calls callback(True/False) whenever the resource becomes connected, synced or disconnected.
    Will always do an initial callback(False) call. Exits without calling callback() if
    exit_event is set
    """
    while not exit_event.is_set():
        if resource.req.connected and resource.req.sync_state == resource.RESOURCE_SYNC_STATE_SYNCED:
            callback(True)
        elif not resource.req.connected or resource.req.sync_state == resource.RESOURCE_SYNC_STATE_UNSYNCED:
            callback(False)
        yield from asyncio.sleep(0.5)


